        ; Check 11: the tick key never moves the operands or plants TXS at step_sound_crash_point. 7 cycles, as the passing path of the original (LDA abs, BNE taken).
nop
nop
jmp step_sound_restore_regs
        !if ((* - .patch_start) & $ffff) > 5 { !error "The patch PROTECTION at $1fe5 has ", ((* - .patch_start) & $ffff), " bytes; the range has 5." } else { !fill 5 - ((* - .patch_start) & $ffff), $ea }
} else {
        lda protection_check_value      ; second protection value (main_loop)
        bne step_sound_restore_regs
}
}
; not executed $1fea-$1ffe
        inc main_loop_prot_key_lo
        inc main_loop_prot_pair_lo
        lda main_loop_prot_key_lo
        cmp #$9a
        bcc step_sound_restore_regs
        ldx #$04                        ; becomes the stack pointer
        lda #$9a                        ; TXS opcode
        sta step_sound_crash_point
step_sound_crash_point
        clc                             ; CLC, replaced by TXS when the protection check fails
step_sound_restore_regs
        pla
        tay
        pla
        tax
        pla
        rts
; Copies of the CIA 1 data direction registers CIADDRA/CIADDRB: frame_update_read_input saves them before it
; reads the joysticks, frame_update_restore_ddr writes them back.
cia1_ddra_save
        !byte $00
cia1_ddrb_save
        !byte $00
; prot_key_tick EOR prot_key_tick_pair, stored by main_loop_protection_check each pass; zero means the
; protection bytes were changed. Read by step_sound_check_protection2. Start value $FF.
protection_check_value
        !byte $ff
